double monte_carlo_hit_or_miss_impl(FunctionPtr f, double a, double b, double fmax, int n_points, unsigned int& seed) {
    if (n_points <= 0) return 0.0;
    if (a > b) std::swap(a, b);
    if (fmax < 0) fmax = -fmax;

    int hits = 0;
    for (int i = 0; i < n_points; ++i) {
        // Generate random x in [a, b]
        seed = seed * 1664525u + 1013904223u;
        double x = a + (b - a) * (seed / 4294967296.0);

        // Generate random y in [0, fmax]
        seed = seed * 1664525u + 1013904223u;
        double y = fmax * (seed / 4294967296.0);

        if (y <= f(x)) {
            hits++;
        }
    }

    return (static_cast<double>(hits) / n_points) * (b - a) * fmax;
}

